steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issues(first: 10, filter: { title: { contains: { value: \"login redirect\" } } }) {
          nodes {
            id
            title
            identifier
            createdAt
            team { name id }
            creator { name id }
            assignee { name id }
          }
        }
      }
    "
  }'
